import { loadFont as loadSans } from "@remotion/google-fonts/Jost";
import { loadFont as loadSerif } from "@remotion/google-fonts/CormorantGaramond";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";

// JB Marketing Digital (cliente "João consultoria") — apresentação do site jbmarketingdigital.com.
// Pedido: não pode faltar videomaker e fotógrafo profissional e gestão de redes sociais; paleta preto e dourado do site.
// Jeito: motion (não vieram fotos nem vídeos); o portfólio aparece pelos prints do próprio site, numa câmera que passeia.
// Identidade do site: preto, dourado, títulos em Cormorant Garamond com a palavra de destaque em itálico dourado,
// texto em Jost. Elemento-fio: o foguete do logo (abre o vídeo, vira a íris para a marca e volta no fim).
// v5: em "Institucionais" entra o começo do vídeo do cliente (a mãe dele falando, 0,3 s), no lugar do colégio.
// v4 (pedido do cliente): no Videomaker, sai o vídeo do site com o rapaz que não é da equipe e entram trechos do vídeo
// do próprio cliente (jb-video.mp4: colégio, perfume, cantora no show), com "Institucionais · Campanhas · Eventos" escrito embaixo.
// v3: abertura refeita (batidas por palavra, inversão claro/escuro e inundação dourada); resto igual à v2.
// v2 (revisão técnica): tudo dentro da área segura x 120–960, y 250–1480 — "aparece / no digital." em duas linhas,
// logo central menor, portfólio e lista de redes sobem. Mesmo texto, mesmo tamanho de letra, mesmo som.
// Locução o locutor (ElevenLabs v3, 37,0 s) entra em V = 0,2 s; os tempos abaixo são da voz (s(x) = x + V).

const { fontFamily: SERIF } = loadSerif("normal", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
loadSerif("italic", { weights: ["500", "600"], subsets: ["latin", "latin-ext"] });
const { fontFamily: SANS } = loadSans("normal", { weights: ["400", "500"], subsets: ["latin", "latin-ext"] });

export const JOAO5_FPS = 30;
export const JOAO5_FRAMES = Math.round(38.6 * JOAO5_FPS);
const V = 0.2;
const s = (x: number) => x + V;
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.25));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const BLACK = "#050505";
const CARD = "#0E0E0E";
const LINE = "rgba(212,175,90,0.32)";
const GOLD = "#D4AF5A";
const GOLD_G = "linear-gradient(100deg, #F3DB98 0%, #D4AF5A 40%, #A9802F 75%, #E9CB7E 100%)";
const gold: React.CSSProperties = { backgroundImage: GOLD_G, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent", fontStyle: "italic", paddingRight: "0.08em" };

// cortes de cena (tempo do vídeo)
const T2 = s(6.85), T3 = s(8.45), T4 = s(15.5), T5 = s(22.2), T6 = s(29.55);

// texto que sobe da linha (máscara), palavra por palavra, e fica parado; some inteiro com desfoque curto
const Words: React.FC<{ t: number; txt: string; at: number[]; out?: number; size: number; color?: string }> = ({ t, txt, at, out, size, color = "#FFFFFF" }) => {
  const o = out === undefined ? 0 : lin(t, out, out + 0.2);
  return (
    <div style={{ display: "flex", justifyContent: "center", gap: size * 0.24, fontFamily: SERIF, fontWeight: 500, fontSize: size, lineHeight: 1.18, letterSpacing: "-0.01em", color, whiteSpace: "nowrap", opacity: 1 - o, filter: o > 0 ? `blur(${(o * 12).toFixed(1)}px)` : undefined }}>
      {txt.split(" ").map((w, i, all) => {
        const g = (all.slice(0, i).join(" ").split("*").length - 1) % 2 === 1 || w.includes("*");
        const e = interpolate(t, [at[Math.min(i, at.length - 1)], at[Math.min(i, at.length - 1)] + 0.42], [0, 1], { ...cl, easing: OUT });
        return (
          <span key={i} style={{ display: "inline-block", overflow: "hidden", paddingBottom: size * 0.12, marginBottom: -size * 0.12 }}>
            <span style={{ display: "inline-block", transform: `translateY(${((1 - e) * 105).toFixed(1)}%)`, ...(g ? gold : {}) }}>{w.replace(/\*/g, "")}</span>
          </span>
        );
      })}
    </div>
  );
};
const Glow: React.FC<{ t: number; y?: number; a?: number }> = ({ t, y = 42, a = 1 }) => (
  <AbsoluteFill style={{ background: `radial-gradient(60% 36% at ${(50 + 5 * Math.sin(t * 0.6)).toFixed(2)}% ${(y + 2 * Math.cos(t * 0.5)).toFixed(2)}%, rgba(212,175,90,${(0.16 * a).toFixed(3)}) 0%, rgba(212,175,90,${(0.05 * a).toFixed(3)}) 48%, rgba(212,175,90,0) 100%)` }} />
);
const Label: React.FC<{ t: number; at: number; out?: number; top: number; children: React.ReactNode }> = ({ t, at, out, top, children }) => {
  const e = k(t, at, 0.4), o = out === undefined ? 0 : lin(t, out, out + 0.2);
  return <div style={{ position: "absolute", left: 0, right: 0, top, textAlign: "center", fontFamily: SANS, fontWeight: 500, fontSize: 30, letterSpacing: "0.26em", color: GOLD, opacity: e * (1 - o), transform: `translateY(${((1 - e) * 20).toFixed(1)}px)` }}>{children}</div>;
};
const Rocket: React.FC<{ w: number; style?: React.CSSProperties }> = ({ w, style }) => (
  <Img src={staticFile("joao/foguete.png")} style={{ position: "absolute", width: w, ...style }} />
);

// ───────── 1 · gancho (v3, mais dinâmico): uma batida por palavra e inversões de cor ─────────
// preto "Tem marca / que só" → INVERTE para claro em "aparece" (a marca que só aparece) → o quadro claro encolhe e
// vira um post perdido que cai → preto "E tem / marca que" → INUNDAÇÃO DOURADA em "domina", letra preta → foguete preto
// cruza o dourado e abre a íris da marca. Tudo na mesma coluna central (x 120–960).
const PAPER = "#F3EEE4";
const INK = "#0A0A0A";
// palavra que bate: entra grande com desfoque e assenta (pouco overshoot), fica parada até sair
const Slam: React.FC<{ t: number; at: number; out: number; size: number; color: string; italic?: boolean; top: number; children: React.ReactNode }> = ({ t, at, out, size, color, italic, top, children }) => {
  if (t < at - 0.01 || t > out + 0.12) return null;
  const e = interpolate(t, [at, at + 0.22], [0, 1], { ...cl, easing: OUT });
  const o = lin(t, out, out + 0.1);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", justifyContent: "center", fontFamily: SERIF, fontWeight: 600, fontStyle: italic ? "italic" : "normal", fontSize: size, lineHeight: 1.05, letterSpacing: "-0.015em", color, whiteSpace: "nowrap", opacity: Math.min(1, e * 2.5) * (1 - o), transform: `scale(${(1.22 - 0.22 * e + 0.06 * o).toFixed(4)})`, filter: e < 1 || o > 0 ? `blur(${((1 - e) * 14 + o * 10).toFixed(1)}px)` : undefined }}>{children}</div>
  );
};
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const INV = s(0.86), SHR = s(2.5), DARK = s(3.85), GOLDT = s(4.8);
  // soco curto de câmera em cada batida (sem tremida), mais a aproximação lenta de fundo
  const beats = [s(0.1), s(0.46), INV, s(1.45), s(3.92), s(4.4), GOLDT, s(5.83)];
  const punch = beats.reduce((acc, b) => acc + interpolate(t, [b, b + 0.05, b + 0.3], [0, 1, 0], { ...cl, easing: OUT }), 0);
  const cam = 1 + 0.1 * interpolate(t, [0, T2], [0, 1], { ...cl, easing: Easing.inOut(Easing.sin) }) + 0.035 * punch;
  // fase clara: o quadro inteiro claro encolhe para um "post" e cai para fora
  const shr = interpolate(t, [SHR, SHR + 0.55], [0, 1], { ...cl, easing: INOUT });
  const fall = interpolate(t, [SHR + 0.6, DARK], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
  const light = t >= INV && t < DARK;
  // inundação dourada saindo do centro de "domina"
  const flood = interpolate(t, [GOLDT - 0.04, GOLDT + 0.3], [0, 1], { ...cl, easing: OUT });
  const fly = interpolate(t, [s(5.95), T2 + 0.05], [0, 1], { ...cl, easing: Easing.bezier(0.45, 0, 0.7, 0.55) });
  // passa por baixo das frases (não cobre "domina")
  const rx = -280 + fly * 1550, ry = 1820 - fly * 700;
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)})` }}>
        {/* A · preto: Tem marca / que só */}
        <Slam t={t} at={s(0.1)} out={s(0.44)} size={190} color="#FFFFFF" top={840}>Tem marca</Slam>
        <Slam t={t} at={s(0.46)} out={INV - 0.03} size={190} color="#FFFFFF" top={840}>que só</Slam>
        {/* B · inversão: papel claro, letra preta */}
        {light ? (
          <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 1920, background: PAPER, overflow: "hidden", borderRadius: 120 * shr, transformOrigin: "50% 50%", transform: `translateY(${(fall * 1500).toFixed(1)}px) scale(${(1 - 0.68 * shr).toFixed(4)}) rotate(${(fall * 14).toFixed(2)}deg)`, boxShadow: shr > 0 ? "0 60px 120px rgba(0,0,0,0.6)" : undefined }}>
            <Slam t={t} at={INV} out={99} size={230} color={INK} top={730}>aparece</Slam>
            <Slam t={t} at={s(1.45)} out={99} size={130} color={INK} top={1000}>no digital.</Slam>
            {/* a marca "só aparece": a palavra perde a cor enquanto a frase termina */}
            <div style={{ position: "absolute", left: 300, right: 300, top: 1210, height: 6, background: INK, transformOrigin: "0% 50%", transform: `scaleX(${k(t, s(1.75), 0.5).toFixed(3)})` }} />
          </div>
        ) : null}
        {/* C · preto: E tem / marca que */}
        <Slam t={t} at={s(3.92)} out={s(4.38)} size={190} color="#FFFFFF" top={840}>E tem</Slam>
        <Slam t={t} at={s(4.4)} out={GOLDT - 0.03} size={190} color="#FFFFFF" top={840}>marca que</Slam>
        {/* D · inundação dourada: domina / o digital., letra preta */}
        {t >= GOLDT - 0.05 ? (
          <AbsoluteFill style={{ backgroundImage: GOLD_G, overflow: "hidden", clipPath: flood < 1 ? `circle(${(flood * 1150).toFixed(0)}px at 540px 960px)` : undefined }}>
            {/* brilho que atravessa o dourado (movimento no fundo, a letra fica parada) */}
            <div style={{ position: "absolute", top: -300, bottom: -300, width: 260, left: -400 + lin(t, GOLDT + 0.3, T2) * 1900, transform: "rotate(14deg)", background: "linear-gradient(90deg, rgba(255,250,230,0) 0%, rgba(255,250,230,0.45) 50%, rgba(255,250,230,0) 100%)" }} />
            <Slam t={t} at={GOLDT} out={99} size={250} color={INK} italic top={720}>domina</Slam>
            <Slam t={t} at={s(5.83)} out={99} size={140} color={INK} top={1010}>o digital.</Slam>
          </AbsoluteFill>
        ) : null}
      </AbsoluteFill>
      {/* o foguete, em preto sobre o dourado, corta o quadro e puxa a íris da marca */}
      {fly > 0 && fly < 1 ? (
        <>
          {[0, 1, 2, 3, 4, 5].map((i) => {
            const f = Math.max(0, fly - 0.035 * (i + 1));
            return <div key={i} style={{ position: "absolute", left: -280 + f * 1500 + 40 - i * 14, top: 1820 - f * 700 + 210 + i * 14, width: 26, height: 26, borderRadius: 4, background: INK, opacity: 0.85 - i * 0.12, transform: "rotate(45deg)" }} />;
          })}
          <Rocket w={300} style={{ left: rx, top: ry, filter: "brightness(0)" }} />
        </>
      ) : null}
    </AbsoluteFill>
  );
};

// ───────── 2 · a marca: o foguete pousa e o letreiro abre por máscara ─────────
const Marca: React.FC<{ t: number }> = ({ t }) => {
  const shrink = interpolate(t, [T3 - 0.15, T3 + 0.55], [0, 1], { ...cl, easing: INOUT });
  const r = pop(t, T2 + 0.05, 0.6);
  const wipe = k(t, s(7.5), 0.7);
  const W = 760 - 460 * shrink;
  // o logo encolhe e vira o topo da cena seguinte
  return (
    <div style={{ position: "absolute", left: 540 - W / 2, top: 780 - 525 * shrink, width: W, height: W * 0.46 }}>
      <Img src={staticFile("joao/foguete.png")} style={{ position: "absolute", left: 0, top: 0, width: W * 0.32, opacity: Math.min(1, r * 2), transform: `translate(${((1 - r) * -120).toFixed(1)}px, ${((1 - r) * 120).toFixed(1)}px) rotate(${((1 - r) * -18).toFixed(1)}deg)` }} />
      <div style={{ position: "absolute", left: W * 0.278, top: W * 0.0, width: W * 0.722, overflow: "hidden", clipPath: `inset(0 ${((1 - wipe) * 100).toFixed(1)}% 0 0)` }}>
        <Img src={staticFile("joao/letreiro.png")} style={{ width: "100%", display: "block", transform: `translateX(${((1 - wipe) * -40).toFixed(1)}px)` }} />
      </div>
    </div>
  );
};

// ───────── 3 · videomaker e fotógrafo: vídeos do próprio cliente, depois a foto do site ─────────
// Trechos limpos (sem legenda) do vídeo que o cliente mandou (464x832): o clipe vertical fica inteiro e nítido no meio do
// cartão, com ele mesmo desfocado cobrindo o fundo. Câmera lenta (0,6–0,65x) para caber cada um na sua batida.
const CLIPS: { a: number; b: number; from: number; rate: number; tag: string }[] = [
  { a: s(9.0), b: s(10.05), from: 0.3, rate: 0.85, tag: "INSTITUCIONAIS" },
  { a: s(10.05), b: s(10.9), from: 29.2, rate: 0.65, tag: "CAMPANHAS" },
  { a: s(10.9), b: s(12.2), from: 4.45, rate: 0.65, tag: "EVENTOS" },
];
const Clip: React.FC<{ t: number; c: (typeof CLIPS)[number]; i: number }> = ({ t, c, i }) => {
  if (t < c.a - 0.02 || t >= c.b) return null;
  const e = i === 0 ? 1 : k(t, c.a, 0.3);
  const enter = [``, `translateX(${((1 - e) * 260).toFixed(1)}px)`, `translateY(${((1 - e) * -220).toFixed(1)}px)`][i];
  const v = (style: React.CSSProperties) => (
    <Sequence from={Math.round(c.a * 30)} layout="none">
      <OffthreadVideo src={staticFile("joao/jb-video.mp4")} trimBefore={Math.round(c.from * 30)} playbackRate={c.rate} muted style={style} />
    </Sequence>
  );
  const z = 1.04 - 0.04 * lin(t, c.a, c.b);
  return (
    <AbsoluteFill style={{ opacity: Math.min(1, e * 2), transform: enter, filter: e < 1 ? `blur(${((1 - e) * 10).toFixed(1)}px)` : undefined }}>
      <AbsoluteFill style={{ filter: "blur(28px) brightness(0.45)", transform: "scale(1.2)" }}>{v({ width: "100%", height: "100%", objectFit: "cover" })}</AbsoluteFill>
      <div style={{ position: "absolute", left: (FW - FH * 464 / 832) / 2, top: 0, width: FH * 464 / 832, height: FH, overflow: "hidden", transform: `scale(${z.toFixed(4)})`, boxShadow: "0 0 60px rgba(0,0,0,0.6)" }}>{v({ width: "100%", height: "100%", objectFit: "cover" })}</div>
    </AbsoluteFill>
  );
};
const FX = 120, FW = 840, FY = 672, FH = 720;
const Portfolio: React.FC<{ t: number }> = ({ t }) => {
  const OUT1 = s(11.7);
  const cardIn = pop(t, s(9.0), 0.6);
  const swap = interpolate(t, [OUT1, OUT1 + 0.45], [0, 1], { ...cl, easing: INOUT });
  // foto01.jpg (658x440) cobre o cartão e aproxima devagar.
  const z2 = 1.0 + 0.07 * lin(t, OUT1, T4);
  return (
    <>
      <div style={{ position: "absolute", left: 0, right: 0, top: 405 }}>
        {t < OUT1 + 0.25 ? (
          <>
            <Words t={t} txt="*Videomaker*" at={[s(9.15)]} size={128} out={OUT1} />
            <Words t={t} txt="e fotógrafo profissional" at={[s(9.75), s(9.85), s(10.4)]} size={76} out={OUT1} />
          </>
        ) : (
          <>
            <Words t={t} txt="o melhor do seu *negócio*" at={[s(12.1), s(12.2), s(12.65), s(12.8), s(13.05)]} size={82} out={T4 - 0.3} />
            <Words t={t} txt="em fotos e vídeos" at={[s(13.65), s(13.7), s(14.2), s(14.28)]} size={82} out={T4 - 0.3} />
          </>
        )}
      </div>
      <div style={{ position: "absolute", left: FX, top: FY, width: FW, height: FH, borderRadius: 40, overflow: "hidden", background: CARD, border: `1.5px solid ${LINE}`, boxSizing: "border-box", boxShadow: "0 40px 90px rgba(0,0,0,0.6)", opacity: Math.min(1, cardIn * 2), transform: `translateY(${((1 - cardIn) * 320).toFixed(1)}px) scale(${(0.92 + 0.08 * cardIn).toFixed(3)})` }}>
        {swap < 1 ? (
          <AbsoluteFill style={{ transform: `translateX(${(-swap * 300).toFixed(1)}px)`, opacity: 1 - swap, filter: swap > 0 ? `blur(${(swap * 14).toFixed(1)}px)` : undefined }}>
            {CLIPS.map((c, i) => <Clip key={i} t={t} c={c} i={i} />)}
          </AbsoluteFill>
        ) : null}
        {swap > 0 ? <Img src={staticFile("joao/foto01.jpg")} style={{ position: "absolute", inset: 0, width: FW, height: FH, objectFit: "cover", objectPosition: "45% 50%", transform: `translateX(${((1 - swap) * 300).toFixed(1)}px) scale(${z2.toFixed(4)})`, transformOrigin: "45% 45%", opacity: swap, filter: swap < 1 ? `blur(${((1 - swap) * 14).toFixed(1)}px)` : undefined }} /> : null}
        {/* selo do tipo de trabalho, no canto do cartão */}
        <div style={{ position: "absolute", left: 30, top: 30, padding: "12px 26px 14px", borderRadius: 999, background: "rgba(5,5,5,0.78)", border: `1.5px solid ${LINE}`, fontFamily: SANS, fontWeight: 500, fontSize: 26, letterSpacing: "0.2em", color: GOLD, opacity: k(t, s(9.3), 0.4) }}>
          {t < OUT1 + 0.2 ? "VÍDEOS" : "FOTOGRAFIA"}
        </div>
      </div>
      {/* os tipos de vídeo: cada um acende em dourado junto com o seu trecho */}
      {t < OUT1 + 0.3 ? (
        <div style={{ position: "absolute", left: 120, right: 120, top: FY + FH + 22, display: "flex", justifyContent: "center", gap: 14, fontFamily: SANS, fontWeight: 500, fontSize: 36, letterSpacing: "0.06em", whiteSpace: "nowrap", opacity: 1 - lin(t, OUT1, OUT1 + 0.25) }}>
          {CLIPS.map((c, i) => {
            const on = t >= c.a && t < c.b + (i === 2 ? 1 : 0);
            const e = k(t, s(9.05), 0.4);
            return (
              <React.Fragment key={i}>
                {i > 0 ? <span style={{ color: "rgba(255,255,255,0.35)", opacity: e }}>·</span> : null}
                <span style={{ color: on ? GOLD : "rgba(255,255,255,0.55)", opacity: e, transform: `translateY(${((1 - e) * 16).toFixed(1)}px)`, display: "inline-block" }}>{["Institucionais", "Campanhas", "Eventos"][i]}</span>
              </React.Fragment>
            );
          })}
        </div>
      ) : (
        <div style={{ position: "absolute", left: 0, right: 0, top: FY + FH + 26, textAlign: "center", fontFamily: SANS, fontWeight: 400, fontSize: 28, color: "rgba(255,255,255,0.5)", opacity: k(t, OUT1 + 0.3, 0.4) }}>portfólio real · jbmarketingdigital.com</div>
      )}
    </>
  );
};

// ───────── 4 · gestão de redes sociais: um item por batida ─────────
const ITENS: [string, number, string][] = [
  ["Estratégia", s(18.12), "M4 18 L9 12 L13 15 L20 7 M15 7 H20 V12"],
  ["Artes", s(19.45), "M4 5 H20 V19 H4 Z M4 15 L9 10 L14 15 M13 13 L16 10 L20 14 M15.5 7.5 h0.01"],
  ["Roteiros", s(20.05), "M6 3 H15 L19 7 V21 H6 Z M15 3 V7 H19 M9 11 H16 M9 14.5 H16 M9 18 H13"],
  ["Relatórios", s(21.12), "M4 20 H20 M7 20 V13 M12 20 V8 M17 20 V4"],
];
const Redes: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: BLACK, transform: `scale(${(1.0 + 0.06 * interpolate(t, [T4, T5], [0, 1], { ...cl, easing: Easing.inOut(Easing.sin) })).toFixed(4)})` }}>
    <Glow t={t} y={30} />
    <Label t={t} at={s(15.9)} top={340}>GESTÃO DE</Label>
    <div style={{ position: "absolute", left: 0, right: 0, top: 390 }}>
      <Words t={t} txt="*redes sociais*" at={[s(16.35), s(16.65)]} size={140} />
    </div>
    {ITENS.map(([nome, at, d], i) => {
      const e = pop(t, at - 0.06, 0.5);
      const chk = lin(t, at + 0.2, at + 0.55);
      const lit = k(t, at, 0.3);
      return (
        <div key={nome} style={{ position: "absolute", left: 150, top: 630 + i * 190, width: 780, height: 160, borderRadius: 30, background: CARD, border: `1.5px solid ${lit > 0.5 ? "rgba(212,175,90,0.55)" : LINE}`, boxSizing: "border-box", display: "flex", alignItems: "center", gap: 38, padding: "0 44px 0 30px", opacity: Math.min(1, e * 2.2), transform: `translateX(${((1 - e) * (i % 2 ? 240 : -240)).toFixed(1)}px) scale(${(0.9 + 0.1 * e).toFixed(3)})` }}>
          <div style={{ width: 100, height: 100, borderRadius: 50, backgroundImage: GOLD_G, display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0, transform: `scale(${(0.4 + 0.6 * pop(t, at, 0.5)).toFixed(3)})` }}>
            <svg width={54} height={54} viewBox="0 0 24 24" fill="none" stroke="#111" strokeWidth={1.9} strokeLinecap="round" strokeLinejoin="round"><path d={d} /></svg>
          </div>
          <div style={{ flex: 1, fontFamily: SERIF, fontWeight: 600, fontSize: 74, color: "#FFFFFF", lineHeight: 1 }}>{nome}</div>
